// -- Small UI -------------------------------------------------
const Bdg=({children,bg,text,dot})=>(<span style={{background:bg,color:text,padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700,display:"inline-flex",alignItems:"center",gap:5,whiteSpace:"nowrap"}}>{dot&&<span style={{width:6,height:6,borderRadius:"50%",background:dot}}/>}{children}</span>);
const RDot=({region})=>{const c=REG_CLR[region]||"#6b7280";return(<span style={{display:"inline-flex",alignItems:"center",gap:6,fontSize:12,fontWeight:600,color:"var(--t-dark)"}}><span style={{width:8,height:8,borderRadius:"50%",background:c}}/>{region}</span>);};
const JBar=({path,step,status})=>{const steps=path==="engaged"?P1_STEPS:NE_STEPS,cur=status==="Converted"?steps.length:Math.min(step,steps.length-1);return(<div style={{display:"flex",gap:3}}>{steps.map((s,i)=>(<div key={i} title={s} style={{flex:1,height:5,borderRadius:3,background:i<cur?EM.green:i===cur?EM.blue:"var(--t-border)",opacity:status==="Completed"?.4:1}}/>))}</div>);};
const Kpi=({label,value,sub,accent,alert,icon})=>(<div style={{background:"var(--t-bgw)",borderRadius:12,padding:"18px 20px",border:`1px solid ${alert?"#dc262630":"var(--t-border)"}`,position:"relative",overflow:"hidden",boxShadow:"0 2px 12px rgba(0,0,0,.07)"}}><div style={{position:"absolute",top:0,left:0,width:4,height:"100%",background:accent,borderRadius:"12px 0 0 12px"}}/><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div><div style={{fontSize:10,color:"var(--t-mid)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:8}}>{label}</div><div style={{fontSize:32,fontWeight:900,color:alert?EM.red:"var(--t-dark)",lineHeight:1,letterSpacing:"-0.02em"}}>{value}</div>{sub&&<div style={{fontSize:11,color:"var(--t-light)",marginTop:5}}>{sub}</div>}</div>{icon&&<span style={{fontSize:20,opacity:.3}}>{icon}</span>}</div></div>);

// -- Search Overlay (⌘K) ─────────────────────────────────────
function SearchOverlay({clients,onClose,onOpen}){
  const [q,setQ]=useState("");
  const [sReg,setSReg]=useState("All");
  const [sPkg,setSPkg]=useState("All");
  const [sAM,setSAM]=useState("All");
  const [sFrom,setSFrom]=useState("");
  const [sTo,setSTo]=useState("");
  const inpRef=useRef(null);
  useEffect(()=>{ setTimeout(()=>inpRef.current&&inpRef.current.focus(),50); },[]);
  const allRegs=useMemo(()=>["All",...[...new Set(clients.map(c=>c.region))].sort()],[clients]);
  const allAMs=useMemo(()=>["All",...[...new Set(clients.flatMap(c=>parseAMs(c.ams)))].sort()],[clients]);
  const activeF=[sReg,sPkg,sAM,sFrom,sTo].filter(v=>v&&v!=="All").length;
  const clearAll=()=>{ setQ(""); setSReg("All"); setSPkg("All"); setSAM("All"); setSFrom(""); setSTo(""); };
  const res=useMemo(()=>{
    let l=[...clients];
    if(sReg!=="All") l=l.filter(c=>c.region===sReg);
    if(sPkg!=="All") l=l.filter(c=>c.pkg===sPkg);
    if(sAM!=="All") l=l.filter(c=>parseAMs(c.ams).includes(sAM));
    if(sFrom) l=l.filter(c=>c.submitted&&c.submitted>=sFrom);
    if(sTo) l=l.filter(c=>c.submitted&&c.submitted<=sTo);
    if(!q.trim()) return l.slice(0,30);
    const lq=q.toLowerCase();
    return l.filter(c=>`${c.id} ${c.country} ${c.region} ${c.ams}`.toLowerCase().includes(lq)).slice(0,30);
  },[clients,q,sReg,sPkg,sAM,sFrom,sTo]);
  return(
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,.62)",backdropFilter:"blur(6px)",zIndex:1100,display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"72px 16px 16px"}} onClick={onClose}>
      <div style={{width:"100%",maxWidth:640,background:"var(--t-bgw)",borderRadius:18,overflow:"hidden",boxShadow:"0 28px 80px rgba(0,0,0,.45)",border:"1px solid var(--t-border)",display:"flex",flexDirection:"column",maxHeight:"80vh"}} onClick={e=>e.stopPropagation()}>
        {/* Header */}
        <div style={{padding:"16px 18px 12px",borderBottom:"1px solid var(--t-border)",background:"var(--t-bgw)"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
            <span style={{fontSize:18}}>🔍</span>
            <input ref={inpRef} value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==="Escape"&&onClose()} placeholder="Search by name, ID, email, country…" style={{flex:1,border:"none",background:"transparent",fontSize:15,color:"var(--t-dark)",fontFamily:"Inter,Roboto,sans-serif",outline:"none"}}/>
            {(q||activeF>0)&&<button onClick={clearAll} style={{fontSize:11,color:EM.red,background:EM.red+"15",border:`1px solid ${EM.red}33`,borderRadius:6,padding:"3px 8px",cursor:"pointer",fontWeight:700,fontFamily:"inherit"}}>✕ Clear</button>}
            <button onClick={onClose} style={{background:"var(--t-bg)",border:"none",width:28,height:28,borderRadius:"50%",cursor:"pointer",fontSize:16,display:"flex",alignItems:"center",justifyContent:"center",color:"var(--t-mid)"}}>×</button>
          </div>
          {/* Filter chips */}
          <div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}>
            {[
              {label:"Region",val:sReg,set:setSReg,opts:allRegs},
              {label:"Package",val:sPkg,set:setSPkg,opts:["All","Platinum","Gold","Silver","Bronze"]},
              {label:"AM",val:sAM,set:setSAM,opts:allAMs},
            ].map(({label,val,set,opts})=>(
              <select key={label} value={val} onChange={e=>set(e.target.value)} style={{padding:"5px 9px",borderRadius:20,border:`1.5px solid ${val!=="All"?EM.green:"var(--t-border)"}`,fontSize:11,fontWeight:val!=="All"?700:400,background:val!=="All"?EM.green+"15":"var(--t-bg)",color:val!=="All"?EM.greenDark:"var(--t-mid)",cursor:"pointer",fontFamily:"inherit",transition:"all .15s"}}>
                {opts.map(o=><option key={o}>{o==="All"?`All ${label}s`:o}</option>)}
              </select>
            ))}
            <div style={{display:"flex",alignItems:"center",gap:4,fontSize:11,color:"var(--t-mid)"}}>
              <input type="date" value={sFrom} onChange={e=>setSFrom(e.target.value)} style={{padding:"4px 7px",borderRadius:20,border:`1.5px solid ${sFrom?EM.green:"var(--t-border)"}`,fontSize:11,background:sFrom?EM.green+"15":"var(--t-bg)",color:"var(--t-dark)",fontFamily:"inherit",cursor:"pointer"}}/>
              <span>→</span>
              <input type="date" value={sTo} onChange={e=>setSTo(e.target.value)} style={{padding:"4px 7px",borderRadius:20,border:`1.5px solid ${sTo?EM.green:"var(--t-border)"}`,fontSize:11,background:sTo?EM.green+"15":"var(--t-bg)",color:"var(--t-dark)",fontFamily:"inherit",cursor:"pointer"}}/>
            </div>
            <span style={{marginLeft:"auto",fontSize:11,color:"var(--t-light)",fontWeight:600}}>{res.length} result{res.length!==1?"s":""}</span>
          </div>
        </div>
        {/* Results */}
        <div style={{flex:1,overflowY:"auto"}}>
          {res.length>0&&<div>{res.map((c,i)=>{const sc=STATUS[c.status]||STATUS.Active,{flag,lang}=parseCulture(c.culture);return(
            <div key={c.id} onClick={()=>{onOpen(c);onClose();}} style={{display:"flex",alignItems:"center",gap:14,padding:"12px 18px",cursor:"pointer",borderBottom:i<res.length-1?`1px solid var(--t-bg)`:"none",transition:"background .1s"}} onMouseEnter={e=>e.currentTarget.style.background="var(--t-bg)"} onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
              <div style={{width:38,height:38,borderRadius:"50%",background:REG_CLR[c.region]+"22",border:`2px solid ${REG_CLR[c.region]}`,display:"flex",alignItems:"center",justifyContent:"center",color:REG_CLR[c.region],fontWeight:800,fontSize:12,flexShrink:0}}>{initials(c)}</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontWeight:700,fontSize:13,color:"var(--t-dark)"}}>{c.id}</div>
                <div style={{fontSize:11,color:"var(--t-mid)",marginTop:1}}>{c.id} · {c.email}</div>
                <div style={{fontSize:11,color:"var(--t-mid)",marginTop:1}}><span style={{background:"var(--t-bg)",border:"1px solid var(--t-border)",borderRadius:4,padding:"1px 5px",fontSize:10,fontWeight:700,color:"var(--t-mid)",marginRight:4}}>{flag}</span>{c.country} · {lang} · {parseAMs(c.ams).join(", ")}</div>
              </div>
              <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:4}}>
                <Bdg bg={sc.bg} text={sc.text} dot={sc.dot}>{c.status}</Bdg>
                <span style={{fontSize:10,color:PKG_CLR[c.pkg],fontWeight:700}}>◆ {c.pkg}</span>
                <RDot region={c.region}/>
              </div>
            </div>
          );})}</div>}
          {(q.trim()||activeF>0)&&res.length===0&&<div style={{padding:40,textAlign:"center",color:"var(--t-light)"}}><div style={{fontSize:28,marginBottom:8}}>🔍</div><div style={{fontSize:14,fontWeight:700,color:"var(--t-dark)",marginBottom:4}}>No results</div><div style={{fontSize:12}}>Try adjusting your filters or search term</div></div>}
          {!q.trim()&&activeF===0&&<div style={{padding:"16px 18px 20px"}}><div style={{fontSize:11,color:"var(--t-light)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:12}}>Quick tips</div>{["Search by full name, first name, or last name","Use client ID (e.g. CL003) for exact match","Filter by Region, Package, or Account Manager","Use date range to find submissions in a period"].map((t,i)=><div key={i} style={{fontSize:12,color:"var(--t-mid)",marginBottom:8,display:"flex",gap:8}}><span style={{color:EM.green,fontWeight:700}}>›</span>{t}</div>)}</div>}
        </div>
      </div>
    </div>
  );
}

// -- Client Modal ---------------------------------------------
function Modal({client,onClose,onUpdate,isMobile}){
  const [con,setCon]=useState(client.contacted);
  const d=daysSince(client.submitted),sc=STATUS[client.status]||STATUS.Active,rc=REG_CLR[client.region]||EM.green;
  const {flag,lang}=parseCulture(client.culture);
  const steps=client.path==="engaged"?P1_STEPS:NE_STEPS,cur=Math.min(client.step,steps.length-1);
  return(
    <div style={{position:"fixed",inset:0,background:"rgba(64,64,65,.55)",backdropFilter:"blur(4px)",zIndex:1000,display:"flex",alignItems:isMobile?"flex-end":"center",justifyContent:"center",padding:isMobile?0:24}} onClick={onClose}>
      <div style={{background:"var(--t-bgw)",borderRadius:isMobile?"18px 18px 0 0":20,width:"100%",maxWidth:isMobile?"100%":520,maxHeight:isMobile?"92vh":"none",overflow:"hidden",overflowY:isMobile?"auto":"visible",boxShadow:"0 20px 60px rgba(0,0,0,.18)",border:`1px solid var(--t-border)`}} onClick={e=>e.stopPropagation()}>
        <div style={{background:EM.dark,padding:"22px 26px 18px"}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div style={{display:"flex",gap:14,alignItems:"center"}}>
              <div><div style={{fontSize:18,fontWeight:800,color:EM.white}}>{client.id}</div><div style={{fontSize:12,color:"#aaa",marginTop:2}}>{parseAMs(client.ams).join(", ")}</div></div>
            </div>
            <button onClick={onClose} style={{background:"rgba(255,255,255,.1)",border:"none",color:EM.white,width:30,height:30,borderRadius:"50%",cursor:"pointer",fontSize:16,display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
          </div>
          <div style={{display:"flex",gap:8,marginTop:12,flexWrap:"wrap"}}>
            <Bdg bg={sc.bg} text={sc.text} dot={sc.dot}>{client.status}</Bdg>
            <span style={{background:PKG_CLR[client.pkg]+"22",color:PKG_CLR[client.pkg],padding:"3px 10px",borderRadius:20,fontSize:11,fontWeight:700}}>◆ {client.pkg}</span>
            <RDot region={client.region}/>
            <span style={{fontSize:11,color:"rgba(255,255,255,.5)",fontWeight:600}}><span style={{background:"var(--t-bg)",border:"1px solid var(--t-border)",borderRadius:4,padding:"1px 5px",fontSize:10,fontWeight:700,color:"var(--t-mid)",marginRight:4}}>{flag}</span>{lang}</span>
          </div>
        </div>
        <div style={{padding:"20px 26px"}}>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14}}>
            <div style={{background:"var(--t-bg)",borderRadius:10,padding:"12px 14px"}}><div style={{fontSize:10,color:"var(--t-light)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:5}}>Country</div><div style={{fontSize:14,fontWeight:700,color:"var(--t-dark)"}}>🌍 {client.country}</div></div>
            <div style={{background:"var(--t-bg)",borderRadius:10,padding:"12px 14px"}}><div style={{fontSize:10,color:"var(--t-light)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:5}}>Language</div><div style={{fontSize:14,fontWeight:700,color:"var(--t-dark)"}}><span style={{background:"var(--t-bg)",border:"1px solid var(--t-border)",borderRadius:4,padding:"1px 5px",fontSize:10,fontWeight:700,color:"var(--t-mid)",marginRight:4}}>{flag}</span>{lang}</div><div style={{fontSize:10,color:"var(--t-light)",marginTop:2}}>{client.culture}</div></div>
          </div>
          <div style={{background:"var(--t-bg)",borderRadius:10,padding:"12px 14px",marginBottom:14}}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}><span style={{fontSize:10,color:"var(--t-mid)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em"}}>Journey Progress</span><span style={{fontSize:11,color:EM.blue,fontWeight:600}}>{steps[cur]}</span></div>
            <JBar path={client.path} step={client.step} status={client.status}/>
            <div style={{display:"flex",justifyContent:"space-between",marginTop:5}}><span style={{fontSize:10,color:"var(--t-light)"}}>Step {cur+1}/{steps.length} · {client.path==="engaged"?"Engaged":"Non-engaged"}</span><span style={{fontSize:10,fontWeight:700,color:urgClr(d)}}>⏱ {d}d since submission</span></div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14}}>
            <div style={{background:"var(--t-bg)",borderRadius:10,padding:"12px 14px"}}><div style={{fontSize:10,color:"var(--t-light)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:5}}>Status</div><div style={{fontSize:13,fontWeight:700,color:sc.text}}>{client.status}</div></div>
            <div style={{background:"var(--t-bg)",borderRadius:10,padding:"12px 14px"}}><div style={{fontSize:10,color:"var(--t-light)",fontWeight:700,textTransform:"uppercase",letterSpacing:".08em",marginBottom:5}}>Account Manager</div><div style={{fontSize:13,fontWeight:700,color:"var(--t-dark)"}}>{parseAMs(client.ams).join(", ")||"—"}</div></div>
          </div>
          <div style={{display:"flex",gap:10,marginBottom:14}}>
            <button onClick={()=>setCon(!con)} style={{flex:1,padding:11,borderRadius:10,border:`1.5px solid ${con?EM.blue:"var(--t-border)"}`,background:con?EM.blue+"12":"var(--t-bgw)",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8,fontFamily:"Inter,Roboto,sans-serif",fontWeight:700,fontSize:13,color:con?EM.blue:"var(--t-mid)",transition:"all .15s"}}>{con?"✅":"⬜"} 📋 Contacted</button>
            <div style={{flex:1,padding:11,borderRadius:10,border:`1.5px solid ${client.deposited?EM.green:"var(--t-border)"}`,background:client.deposited?EM.green+"12":"var(--t-bgw)",display:"flex",alignItems:"center",justifyContent:"center",gap:8,fontWeight:700,fontSize:13,color:client.deposited?EM.green:"var(--t-mid)"}}>{client.deposited?"✅":"⬜"} 💰 Deposited</div>
          </div>
          <button onClick={()=>{onUpdate(client.id,{contacted:con});onClose();}} style={{width:"100%",padding:13,borderRadius:10,border:"none",background:EM.green,color:EM.white,fontWeight:800,fontSize:14,cursor:"pointer",fontFamily:"Inter,Roboto,sans-serif"}}>Save Changes</button>
        </div>
      </div>
    </div>
  );
}

