          <span style={{color:"rgba(255,255,255,.75)"}}>You have</span>
          {overdue.length>0&&<span style={{background:"rgba(220,38,38,.3)",border:"1px solid rgba(220,38,38,.4)",borderRadius:6,padding:"2px 8px",fontWeight:700}}>📞 {overdue.length} uncontacted</span>}
          {depositOverdue.length>0&&<span style={{background:"rgba(217,119,6,.3)",border:"1px solid rgba(217,119,6,.4)",borderRadius:6,padding:"2px 8px",fontWeight:700}}>💰 {depositOverdue.length} deposit overdue</span>}
